UPDATE dashboard_bookings SET property_id = COALESCE(NULLIF(TRIM((SELECT dashboard_id FROM properties WHERE property_code = dashboard_bookings.property_code)), ''), (SELECT id FROM properties WHERE property_code = dashboard_bookings.property_code), 'BELUM-' || property_code), property_name = COALESCE((SELECT name FROM properties WHERE property_code = dashboard_bookings.property_code), 'Properti ' || property_code || ' - kode perlu diperiksa'), note = CASE WHEN (SELECT COUNT(*) FROM properties WHERE property_code = dashboard_bookings.property_code) = 0 AND note NOT LIKE '%KODE PERLU DIPERIKSA%' THEN note || ' - KODE PERLU DIPERIKSA' ELSE note END WHERE created_by = 'import-excel-2026-tambahan-2';
INSERT OR IGNORE INTO finance_entries (id, kind, category_id, category_name, property_id, property_name, entry_date, amount, description, payee, recurrence, created_by, created_at) SELECT b.income_entry_id, 'income', 'income-booking', 'Booking', b.property_id, b.property_name, b.checkin, b.amount, 'Booking ' || b.id || ' - ' || b.guest, b.platform, 'once', b.created_by, b.created_at FROM dashboard_bookings b WHERE b.created_by = 'import-excel-2026-tambahan-2';
SELECT COUNT(*) AS jumlah_booking_tambahan, COALESCE(SUM(amount), 0) AS nilai_booking_tambahan FROM dashboard_bookings WHERE created_by = 'import-excel-2026-tambahan-2';
SELECT COUNT(*) AS jumlah_pemasukan_tambahan, COALESCE(SUM(amount), 0) AS nilai_pemasukan_tambahan FROM finance_entries WHERE created_by = 'import-excel-2026-tambahan-2';
SELECT property_code AS kode, property_id, property_name FROM dashboard_bookings WHERE created_by = 'import-excel-2026-tambahan-2' ORDER BY checkin;
